head.script:
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.bns.BnsPanelToGroupBox(pnl_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Srch);

        // 호출파라미터설정
        scwin.setParam();

        // 종목정보 설정
        const vIsuNm = '[' + scwin.objParam.STD_CD + ']' + '  ' + '[' + scwin.objParam.ISU_NM + ']';
        txb_StdCd.setValue(vIsuNm);

        // 수신일 시작일 현재일자 -10일로 설정, 수신일 종료일 현재일자로 설정
        edt_StartDd.setValue($c.ut.cGetMinusDate2(scwin.vCurDate, 10));
        edt_EndDd.setValue(scwin.vCurDate);

        // 신용평가 수신정보 내역 조회
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_StartDd_onclick
 * @description img_StartDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StartDd_onclick = function() {
    try {
        popUpCalendar2(edt_StartDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.img_StartDd_onclick" });
    }
};

/**
 * @method
 * @name img_EndDd_onclick
 * @description img_EndDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EndDd_onclick = function() {
    try {
        popUpCalendar2(edt_EndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.img_EndDd_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30201.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Srch_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Srch_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.btn_Srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30201.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Delete_onclick = async function() {
    try {
        if (dts_List.getRowCount() === 0) return;
        processGp = 5;
        await scwin.delete();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30201.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        scwin.check(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30201.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (processGp === 1) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        }
        if (processGp === 5) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        }
        dts_List.Reset();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30201.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (processGp === 1) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        }
        if (processGp === 5) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30201.trs_Save_OnFail" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.STD_CD = arrPar[0].STD_CD;
        scwin.objParam.ISU_NM = arrPar[0].BND_ISU_NM;
    }
};

/**
 * @method
 * @name listSync
 * @description 신용평가 수신정보 내역을 조회 한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    const dsNm = 'BNS_CLS_CREDIT_LIST';
    const qryId = 'lds.stf.bnscls.select.listCreditValuRcv';
    let param = '&{P}V_RCV_DD=' + edt_StartDd.getValue();
    param += '&{P}V_RCV_DD_END=' + edt_EndDd.getValue();
    param += '&{P}V_CREDIT_VALU_INST_NM=' + ''; // 신용평가수신 및 처리 수신내역 목록 조회용도
    param += '&{P}V_SAME_GRD_YN=' + ''; // 신용평가수신 및 처리 수신내역 목록 조회용도
    param += '&{P}V_STD_CD=' + scwin.objParam.STD_CD;
    $c.bns.fn_SearchBns('ULDBNS30201.xml', dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name delete
 * @description 중복수신된 수신정보 내역을 삭제 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    // 등급기준이 선택된 값이 있는지 확인한다.
    let total = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "CHK") === "T") {
            total++;
        }
    }
    if (total === 0) {
        await $c.win.alert("선택된 항목이 없습니다.");
        return;
    }
    if (!confirm("신용등급 데이터를 삭제하시겠습니까?")) return false;
    let V_RCV_DD;
    let V_CREDIT_VALU_INST_CD;
    let V_STD_CD;
    let V_RCV_ISU_NO;

    // 선택된값 1개만 전송
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (dts_List.getCellData(i, "CHK") === "T") {
            V_RCV_DD = dts_List.getCellData(i, "RCV_DD");
            V_CREDIT_VALU_INST_CD = dts_List.getCellData(i, "CREDIT_VALU_INST_CD");
            V_STD_CD = dts_List.getCellData(i, "STD_CD");
            V_RCV_ISU_NO = dts_List.getCellData(i, "RCV_ISU_NO");
        }
    }

    // 삭제대상의 수신일체크 (당일 수신된 데이터만 삭제가능)
    // alert(vCurDate +'::'+ V_RCV_DD);
    if (scwin.vCurDate !== V_RCV_DD) {
        await $c.win.alert("당일 수신된 데이터만 삭제 할 수 있습니다.");
        return;
    }
    let url = "/bns/CreditValu.do?method=processCreditValuRcvDelete";
    url += "&SCREN_ID=" + 'ULDBNS30201.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&RCV_DD=" + V_RCV_DD;
    url += "&CREDIT_VALU_INST_CD=" + V_CREDIT_VALU_INST_CD;
    url += "&STD_CD=" + V_STD_CD;
    url += "&RCV_ISU_NO=" + V_RCV_ISU_NO;
    // alert(url);

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_Save.Post();
};

/**
 * @method
 * @name check
 * @description 마지막 선택 row만 체크박스 선택
 * @param {*} nRow nRow
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.check = function(nRow, colid) {
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        dts_List.setCellData(i, "CHK", "F");
    }
    dts_List.setBroadcast(true, true);
    dts_List.setCellData(nRow, "CHK", "T");
};

/**
 * @method
 * @name grd_List_CanColumnPosChange
 * @description grd List Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
